/// Revisions: 2026-07-28, ext-tasks/2026-07-28.
sealed class InputRequest implements ServerRequest {
  /// Reads the branch [json] names; an unrecognised one is kept as [UnknownInputRequest].
  factory InputRequest.fromJson(Map<String, Object?> json) {
    switch (json['method']) {
      case 'sampling/createMessage':
        return CreateMessageRequest.fromJson(json);
      case 'roots/list':
        return ListRootsRequest.fromJson(json);
      case 'elicitation/create':
        return ElicitRequest.fromJson(json);
    }
    return UnknownInputRequest.fromJson(json);
  }

  @override
  Map<String, Object?> toJson();
}

