/// Direction of an MCP message.
enum McpDirection { clientToServer, serverToClient }

/// One MCP method as the schema defines it.
final class McpMethodSpec {
  const McpMethodSpec(this.method, this.direction, this.isRequest, this.messageType, this.paramsType, this.resultType, this.revisions);
  final String method;
  final McpDirection direction;
  final bool isRequest;
  /// Schema definition of the whole message.
  final String messageType;
  /// Schema definition of `params`, when the schema names one.
  final String? paramsType;
  /// Schema definition of the result (requests only).
  final String? resultType;
  /// Sources that define it (core revisions, `ext-tasks/<rev>`).
  final Set<String> revisions;
}

